    font-size: 0.9rem;
    font-family: inherit;
    min-height: 40px;
    max-height: 120px;
    outline: none;
    transition: border-color 0.2s;
}

.message-input:focus {
    border-color: #1264a3;
}

.send-btn {
    padding: 10px 20px;
    background: #1264a3;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #0e4f82;
}

