+}
+
+.sidebar-header h2 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #fff;
+}
+
+.channel-list {
+    list-style: none;
+    padding: 0;
+    margin: 0;
+    overflow-y: auto;
+    flex: 1;
+}
+
+.channel-item {
+    padding: 10px 16px;
+    cursor: pointer;
+    border-bottom: 1px solid #2c2f33;
+    position: relative;
+    transition: background 0.15s;
+}
+
+.channel-item:hover {
+    background: #2c2f33;
+}
+
+.channel-item.active {
+    background: #1164a3;
+    color: #fff;
+}
+
+.channel-name {
+    font-weight: 600;
+    font-size: 0.95rem;
+    margin-bottom: 2px;
+}
+
+.channel-description {
+    font-size: 0.8rem;
+    color: #999;
+    white-space: nowrap;
+    overflow: hidden;
+    text-overflow: ellipsis;
+}
+
+.channel-item.active .channel-description {
+    color: #ddd;
+}
+
+.unread-badge {
+    position: absolute;
+    top: 12px;
+    right: 12px;
+    background: #e74c3c;
