+    flex-direction: column;
+    background: #fff;
+    min-width: 0;
+}
+
+.message-area.thread-open {
+    max-width: 55%;
+}
+
+.message-header {
+    padding: 14px 20px;
+    border-bottom: 1px solid #e0e0e0;
+    background: #fafafa;
+}
+
+.message-header h3 {
+    margin: 0 0 4px;
+    font-size: 1.1rem;
+    color: #1a1d21;
+}
+
+.message-header p {
+    margin: 0;
+    font-size: 0.85rem;
+    color: #666;
+}
+
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px 20px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 10px;
+    color: #888;
+    font-size: 0.85rem;
+}
+
+.message-item {
+    padding: 8px 12px;
+    margin-bottom: 4px;
+    border-radius: 6px;
+    position: relative;
+    transition: background 0.1s;
+}
+
+.message-item:hover {
+    background: #f5f5f5;
+}
+
+.message-meta {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 2px;
+}
+
+.message-author {
+    font-weight: 700;
+    font-size: 0.9rem;
+    color: #1a1d21;
+}
+
+.message-time {
+    font-size: 0.75rem;
+    color: #999;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+    color: #333;
+    word-wrap: break-word;
+}
+
+.reaction-row {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 6px;
+    margin-top: 6px;
+}
+
+.reaction-badge {
+    display: inline-flex;
+    align-items: center;
+    gap: 3px;
+    background: #f0f4f8;
+    border: 1px solid #dce3ea;
+    border-radius: 12px;
+    padding: 2px 8px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.reaction-badge:hover {
+    background: #dce3ea;
+}
+
+.thread-link {
+    margin-top: 4px;
+    font-size: 0.8rem;
+    color: #1264a3;
+    cursor: pointer;
+    font-weight: 500;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+.message-actions {
+    position: absolute;
+    top: 4px;
+    right: 8px;
+    display: flex;
+    gap: 4px;
+    background: #fff;
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 2px 4px;
+    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
+}
+
+.action-btn {
